From cfe4b5c4aaa0d86f9d98095515ae6582a053cc47 Mon Sep 17 00:00:00 2001
From: Lukas Larsson <lukas@erlang.org>
Date: Mon, 27 Feb 2017 10:11:47 +0100
Subject: [PATCH] erts: Fix emasculation of binaries in port_control

This fixes a bug introduced in 3671dd2d

diff --git a/erts/emulator/beam/io.c b/erts/emulator/beam/io.c
index 9bf29ee230..38e403d91a 100644
--- a/erts/emulator/beam/io.c
+++ b/erts/emulator/beam/io.c
@@ -4889,10 +4889,18 @@ erts_port_control(Process* c_p,
 	    copy = 1;
 	else {
             ProcBin *pb = (ProcBin *) ebinp;
+            int offset = bufp - pb->val->orig_bytes;

-            if (pb->flags)
+	    ASSERT(pb->val->orig_bytes <= bufp
+		   && bufp + size <= pb->val->orig_bytes + pb->val->orig_size);
+
+            if (pb->flags) {
                 erts_emasculate_writable_binary(pb);

+                /* The procbin may have been reallocated, so update bufp */
+                bufp = pb->val->orig_bytes + offset;
+            }
+
 	    binp = pb->val;
 	    ASSERT(bufp <= bufp + size);
 	    ASSERT(binp->orig_bytes <= bufp
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by improper handling of the `ProcBin` structure during the emasculation process, which could lead to incorrect memory references and potential data corruption when the binary was modified. Specifically, the original pointer `bufp` was not updated after the binary was emasculated, risking access to invalid memory locations.

        Commit message:
        erts: Fix emasculation of binaries in port_control

This fixes a bug introduced in 3671dd2d  

        Patch:

 ErtsPortOpResult
 erts_port_control(Process* c_p,
 		  Port *prt,
 		  unsigned int command,
 		  Eterm data,
 		  Eterm *retvalp)
 {
     ErtsPortOpResult res;
     char *bufp = NULL;
     ErlDrvSizeT size = 0;
     int try_call;
     int tmp_alloced = 0;
     erts_aint32_t sched_flags;
     Binary *binp;
     int copy;
     ErtsProc2PortSigData *sigdp;

     sched_flags = erts_smp_atomic32_read_nob(&prt->sched.flags);
     if (sched_flags & ERTS_PTS_FLG_EXIT)
 	return ERTS_PORT_OP_BADARG;

     try_call = !(sched_flags & ERTS_PTS_FLGS_FORCE_SCHEDULE_OP);

     if (is_binary(data) && binary_bitoffset(data) == 0) {
 	byte *bytep;
 	ERTS_DECLARE_DUMMY(Uint bitoffs);
 	ERTS_DECLARE_DUMMY(Uint bitsize);
 	ERTS_GET_BINARY_BYTES(data, bytep, bitoffs, bitsize);
 	bufp = (char *) bytep;
 	size = binary_size(data);
     } else {
 	int r;

 	if (!try_call) {
 	    if (erts_iolist_size(data, &size))
 		return ERTS_PORT_OP_BADARG;
 	    bufp = erts_alloc(ERTS_ALC_T_DRV_CTRL_DATA, size);
 	    r = erts_iolist_to_buf(data, bufp, size);
 	    ASSERT(r == 0);
 	}
 	else {
 	    /* Try with an 8KB buffer first (will often be enough I guess). */
 	    size = 8*1024;
 	    bufp = erts_alloc(ERTS_ALC_T_TMP, size);
 	    tmp_alloced = 1;

 	    r = erts_iolist_to_buf(data, bufp, size);
 	    if (ERTS_IOLIST_TO_BUF_SUCCEEDED(r)) {
 		size -= r;
 	    } else {
 		if (r == ERTS_IOLIST_TO_BUF_TYPE_ERROR) { /* Type error */
 		    erts_free(ERTS_ALC_T_TMP, bufp);
 		    return ERTS_PORT_OP_BADARG;
 		}
 		else {
 		    ASSERT(r == ERTS_IOLIST_TO_BUF_OVERFLOW); /* Overflow */
 		    erts_free(ERTS_ALC_T_TMP, bufp);
 		    if (erts_iolist_size(data, &size))
 			return ERTS_PORT_OP_BADARG; /* Type error */
 		}
 		bufp = erts_alloc(ERTS_ALC_T_TMP, size);
 		r = erts_iolist_to_buf(data, bufp, size);
 		ASSERT(r == 0);
 	    }
 	}
     }

     if (try_call) {
 	char resp_buf[ERL_ONHEAP_BIN_LIMIT];
 	char* resp_bufp = &resp_buf[0];
 	ErlDrvSizeT resp_size = sizeof(resp_buf);
 	ErtsTryImmDrvCallResult try_call_res;
 	ErtsTryImmDrvCallState try_call_state
 	    = ERTS_INIT_TRY_IMM_DRV_CALL_STATE(
 		c_p,
 		prt,
 		ERTS_PORT_SFLGS_INVALID_LOOKUP,
 		0,
 		0,
 		am_control);

 	try_call_res = try_imm_drv_call(&try_call_state);
 	switch (try_call_res) {
 	case ERTS_TRY_IMM_DRV_CALL_OK: {
 	    Eterm *hp;
 	    Uint hsz;
 	    int control_flags;

 	    res = call_driver_control(c_p->common.id,
 				      prt,
 				      command,
 				      bufp,
 				      size,
 				      &resp_bufp,
 				      &resp_size);

 	    control_flags = prt->control_flags;

 	    finalize_imm_drv_call(&try_call_state);
 	    if (tmp_alloced)
 		erts_free(ERTS_ALC_T_TMP, bufp);
 	    if (res == ERTS_PORT_OP_BADARG) {
 		return ERTS_PORT_OP_BADARG;
 	    }

 	    hsz = port_control_result_size(control_flags,
 					   resp_bufp,
 					   &resp_size,
 					   &resp_buf[0]);
 	    hp = HAlloc(c_p, hsz);
 	    *retvalp = write_port_control_result(control_flags,
 						 resp_bufp,
 						 resp_size,
 						 &resp_buf[0],
 						 &hp,
 						 &c_p->off_heap);
 	    BUMP_REDS(c_p, ERTS_PORT_REDS_CONTROL);
 	    return ERTS_PORT_OP_DONE;
 	}
 	case ERTS_TRY_IMM_DRV_CALL_INVALID_PORT:
 	    if (tmp_alloced)
 		erts_free(ERTS_ALC_T_TMP, bufp);
 	    return ERTS_PORT_OP_BADARG;
 	default:
 	    /* Schedule control() call instead... */
 	    break;
 	}
     }

     /* Convert data into something that can be scheduled */

     copy = tmp_alloced;

     binp = NULL;

     if (is_binary(data) && binary_bitoffset(data) == 0) {
 	Eterm *ebinp = binary_val(data);
 	ASSERT(!tmp_alloced);
 	if (*ebinp == HEADER_SUB_BIN)
 	    ebinp = binary_val(((ErlSubBin *) ebinp)->orig);

 	if (*ebinp != HEADER_PROC_BIN)
 	    copy = 1;
 	else {
             ProcBin *pb = (ProcBin *) ebinp;
+            int offset = bufp - pb->val->orig_bytes;

-            if (pb->flags)
+	    ASSERT(pb->val->orig_bytes <= bufp
+		   && bufp + size <= pb->val->orig_bytes + pb->val->orig_size);
+
+            if (pb->flags) {
                 erts_emasculate_writable_binary(pb);

+                /* The procbin may have been reallocated, so update bufp */
+                bufp = pb->val->orig_bytes + offset;
+            }
+
 	    binp = pb->val;
 	    ASSERT(bufp <= bufp + size);
 	    ASSERT(binp->orig_bytes <= bufp
 		   && bufp + size <= binp->orig_bytes + binp->orig_size);
 	    erts_refc_inc(&binp->refc, 1);
 	}
     }

     if (copy) {
 	char *old_bufp = bufp;
 	bufp = erts_alloc(ERTS_ALC_T_DRV_CTRL_DATA, size);
 	sys_memcpy(bufp, old_bufp, size);
 	if (tmp_alloced)
 	    erts_free(ERTS_ALC_T_TMP, old_bufp);
     }

     sigdp = erts_port_task_alloc_p2p_sig_data();
     sigdp->flags = ERTS_P2P_SIG_TYPE_CONTROL;
     sigdp->u.control.binp = binp;
     sigdp->u.control.command = command;
     sigdp->u.control.bufp = bufp;
     sigdp->u.control.size = size;

     res = erts_schedule_proc2port_signal(c_p,
 					 prt,
 					 c_p->common.id,
 					 retvalp,
 					 sigdp,
 					 0,
 					 NULL,
 					 port_sig_control);
     if (res != ERTS_PORT_OP_SCHEDULED) {
 	cleanup_scheduled_control(binp, bufp);
 	return ERTS_PORT_OP_BADARG;
     }
     return res;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>
